package com.nthexperience.desktop;

import android.content.Context;
import android.content.res.ColorStateList;
import android.graphics.Color;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Reference-style calculator: large display, memory row, wide zero and tall equals. */
final class TenCalculator extends ViewGroup {
    final DesktopStore store;final TenCalculatorModel model;final LinearLayout display;final TextView history,result,memory;final ViewGroup keypad;
    boolean painted,dark;
    TenCalculator(Context c,DesktopStore store){
        super(c);this.store=store;model=new TenCalculatorModel(GadgetData.get(store,"calculator"));setContentDescription("Nth Calculator");setFocusableInTouchMode(true);
        display=Aero.column(c);display.setPadding(dp(12),dp(6),dp(12),dp(10));TenAppearance.preserve(display);LinearLayout top=new LinearLayout(c);TextView menu=text("≡",22);menu.setContentDescription("Calculator menu");menu.setFocusable(true);menu.setOnClickListener(v->menu(menu));top.addView(menu,new LinearLayout.LayoutParams(dp(36),dp(30)));memory=text("",11);memory.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);memory.setContentDescription("Calculator memory");top.addView(memory,new LinearLayout.LayoutParams(0,-1,1));display.addView(top);
        history=text("",12);history.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);history.setMaxLines(2);history.setContentDescription("Calculator expression");display.addView(history,new LinearLayout.LayoutParams(-1,0,1));result=text("0",43);result.setGravity(Gravity.RIGHT|Gravity.BOTTOM);result.setSingleLine();result.setEllipsize(android.text.TextUtils.TruncateAt.START);result.setTextIsSelectable(true);result.setContentDescription("Calculator result");result.setAccessibilityLiveRegion(ACCESSIBILITY_LIVE_REGION_POLITE);display.addView(result,new LinearLayout.LayoutParams(-1,dp(54)));addView(display);
        keypad=new Keypad(c);TenAppearance.preserve(keypad);String[][] keys={{"MC","MR","M+","M−"},{"C","DEL","÷","×"},{"7","8","9","−"},{"4","5","6","+"},{"1","2","3","="},{"0",".","",""}};
        for(int row=0;row<6;row++)for(int col=0;col<4;col++){String key=keys[row][col];if(key.isEmpty())continue;int x=key.equals(".")?2:col,w=key.equals("0")?2:1,h=key.equals("=")?2:1;int fill=row==0?0xff0078d7:key.equals("C")?0xffff922d:key.equals("=")?0xff008d3c:0xff5b5b5b;TextView button=text(key,row==0?19:25);button.setGravity(Gravity.CENTER);button.setContentDescription("Calculator "+(key.equals("M−")?"M-":key));button.setFocusable(true);button.setClickable(true);int pressed=TenAccent.mix(fill,Color.BLACK,.18f);StateListDrawable background=new StateListDrawable();for(int state:new int[]{android.R.attr.state_pressed,android.R.attr.state_focused,android.R.attr.state_hovered})background.addState(new int[]{state},new ColorDrawable(pressed));background.addState(new int[]{},new ColorDrawable(fill));button.setBackground(background);button.setTextColor(new ColorStateList(new int[][]{new int[]{android.R.attr.state_pressed},new int[]{android.R.attr.state_focused},new int[]{}},new int[]{TenAccent.on(pressed),TenAccent.on(pressed),TenAccent.on(fill)}));button.setOnClickListener(v->press(key));keypad.addView(button,new Cell(row,x,h,w));}
        addView(keypad);appearance();render();
    }
    private int dp(int value){return Aero.dp(getContext(),value);}
    private TextView text(String value,int size){TextView view=new TextView(getContext());view.setText(value);view.setTextSize(size);view.setTypeface(Aero.face(getContext()));view.setIncludeFontPadding(false);return view;}
    void press(String key){model.key(key);GadgetData.save(store,"calculator",model.save());render();}
    private void render(){history.setText(model.history);result.setText(model.display());memory.setText(model.memory==0?"":"M  "+GadgetMath.number(model.memory));result.setTextSize(model.display().length()>20?20:model.display().length()>12?30:43);}
    void appearance(){boolean next=TenAppearance.dark(getContext());if(painted&&dark==next)return;painted=true;dark=next;display.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,next?new int[]{0xff383838,0xff252525}:new int[]{0xffeeeeee,0xffcccccc}));int foreground=next?Color.WHITE:Color.BLACK;result.setTextColor(foreground);history.setTextColor(next?0xffdddddd:0xff333333);memory.setTextColor(next?0xffdddddd:0xff333333);((TextView)((LinearLayout)display.getChildAt(0)).getChildAt(0)).setTextColor(foreground);}
    private void menu(View anchor){PopupMenu menu=new PopupMenu(getContext(),anchor);for(String label:new String[]{"Copy result","Change sign ±","Percent %","Clear memory"})menu.getMenu().add(label).setOnMenuItemClickListener(item->{switch(label){case "Copy result":getContext().getSystemService(android.content.ClipboardManager.class).setPrimaryClip(android.content.ClipData.newPlainText("Calculator result",model.display()));break;case "Change sign ±":press("±");break;case "Percent %":press("%");break;default:press("MC");}return true;});menu.show();}
    @Override protected void onMeasure(int widthSpec,int heightSpec){int w=MeasureSpec.getSize(widthSpec),h=MeasureSpec.getSize(heightSpec);if(MeasureSpec.getMode(heightSpec)==MeasureSpec.UNSPECIFIED)h=dp(480);setMeasuredDimension(w,h);boolean wide=w>=dp(520)&&h<dp(440);int gap=dp(4),displayWidth=wide?Math.round(w*.31f):w-gap*2,displayHeight=wide?h-gap*2:Math.max(dp(104),Math.min(dp(160),Math.round(h*.25f)));display.measure(MeasureSpec.makeMeasureSpec(Math.max(1,displayWidth),MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(Math.max(1,displayHeight),MeasureSpec.EXACTLY));keypad.measure(MeasureSpec.makeMeasureSpec(Math.max(1,wide?w-displayWidth-gap*3:w-gap*2),MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(Math.max(1,wide?h-gap*2:h-displayHeight-gap*3),MeasureSpec.EXACTLY));}
    @Override protected void onLayout(boolean changed,int l,int t,int r,int b){int gap=dp(4);display.layout(gap,gap,gap+display.getMeasuredWidth(),gap+display.getMeasuredHeight());boolean wide=getWidth()>=dp(520)&&getHeight()<dp(440);int x=wide?display.getRight()+gap:gap,y=wide?gap:display.getBottom()+gap;keypad.layout(x,y,x+keypad.getMeasuredWidth(),y+keypad.getMeasuredHeight());}
    @Override protected void dispatchDraw(android.graphics.Canvas canvas){canvas.drawColor(Color.BLACK);super.dispatchDraw(canvas);}
    @Override public boolean dispatchKeyEvent(KeyEvent event){if(event.getAction()==KeyEvent.ACTION_DOWN){String key=null;int code=event.getKeyCode();if(code==KeyEvent.KEYCODE_ENTER||code==KeyEvent.KEYCODE_NUMPAD_ENTER)key="=";else if(code==KeyEvent.KEYCODE_DEL)key="DEL";else if(code==KeyEvent.KEYCODE_ESCAPE)key="C";else{char c=(char)event.getUnicodeChar();if("0123456789.+-*/=%".indexOf(c)>=0&&c!=0)key=String.valueOf(c);}if(key!=null&&!event.isCtrlPressed()&&!event.isAltPressed()&&!event.isMetaPressed()){press(key);return true;}}return super.dispatchKeyEvent(event);}
    private static final class Cell extends LayoutParams {final int row,col,rows,cols;Cell(int row,int col,int rows,int cols){super(0,0);this.row=row;this.col=col;this.rows=rows;this.cols=cols;}}
    private final class Keypad extends ViewGroup {Keypad(Context c){super(c);setContentDescription("Calculator keypad");}protected void onMeasure(int ws,int hs){int w=MeasureSpec.getSize(ws),h=MeasureSpec.getSize(hs),gap=dp(3);setMeasuredDimension(w,h);for(int i=0;i<getChildCount();i++){View child=getChildAt(i);Cell p=(Cell)child.getLayoutParams();child.measure(MeasureSpec.makeMeasureSpec(Math.max(1,Math.round(w*p.cols/4f)-gap),MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(Math.max(1,Math.round(h*p.rows/6f)-gap),MeasureSpec.EXACTLY));if(child instanceof TextView)((TextView)child).setTextSize(h/6f<dp(37)?14:p.row==0?19:25);}}protected void onLayout(boolean changed,int l,int t,int r,int b){for(int i=0;i<getChildCount();i++){View child=getChildAt(i);Cell p=(Cell)child.getLayoutParams();int x=Math.round(getWidth()*p.col/4f),y=Math.round(getHeight()*p.row/6f);child.layout(x,y,x+child.getMeasuredWidth(),y+child.getMeasuredHeight());}}}
}
